"""
       blending function increasing concave
       d = delta x = xabs - xdr
       u = uncertainty radius of xabs estimate error
       s = tuning scale factor

       eq 3.12

       returns blend
    """
def blendConcaveInc(d: Any = 0.0, u: Any = 1.0, s: Any = 1.0, h: Any = 1.0) -> object {
    d = float(d);
    u = float(u);
    s = float(s);
    m = (2 * s) - u - d;
    if (m == 0) {
        return h;
    }
    if (d >= s) {
        return h;
    } else {
        b = (h * (s - u)) / m;
    }
    return b;
}

"""Calculates the lande g factor given L, S and J

    .. math::
        g = 1 + \\frac{J(J+1) + S(S+1) - L(L+1)}{2J(J+1)}

    Reference: Sobel'man, I.I. Introduction to the
        Theory of Atomic Spectra. 1972. pp. 277

    Args:
        L (float): L number
        S (float): S number
        J (float): J number

    Returns:
        float: lande g factor
    """
def lande_g(L: Any, S: Any, J: Any) -> object {
    return (
        1.0
        + (
            (((J * (J + 1.0)) + (S * (S + 1.0))) - (L * (L + 1.0)))
            / (2.0 * J * (J + 1.0))
        )
    );
}

